import{_ as e,o as a,c as d,a2 as n}from"./chunks/framework.DToEn73J.js";const m=JSON.parse('{"title":"术语表","description":"","frontmatter":{"title":"术语表","chapter":"附录","order":1,"summary":"全站统一术语的中英对照与一句话定义，避免各页各说各话。"},"headers":[],"relativePath":"glossary.md","filePath":"glossary.md","lastUpdated":1788254264000}'),r={name:"glossary.md"};function o(i,t,s,c,l,g){return a(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><blockquote><p>全站统一术语表。新增术语请以本表为准；正文首次出现外文术语时附中文说明。相关页用根相对路径链接。</p></blockquote><table tabindex="0"><thead><tr><th>术语</th><th>中文</th><th>一句话定义</th><th>相关页</th></tr></thead><tbody><tr><td>Agent Loop</td><td>智能体循环</td><td>感知-思考-行动（Perceive–Think–Act）的反复执行循环，是 Agent 的运行骨架</td><td><a href="/fk-ai-agent/01-agent-basics/agent-loop">/01-agent-basics/agent-loop</a></td></tr><tr><td>Tool</td><td>工具</td><td>Agent 可调用的外部能力，以 JSON Schema 描述输入/输出契约</td><td><a href="/fk-ai-agent/01-agent-basics/tool-abstraction">/01-agent-basics/tool-abstraction</a></td></tr><tr><td>Skill</td><td>技能</td><td>预置的可复用能力包（提示词/脚本/工作流），区别于 MCP 的协议化远程能力</td><td><a href="/fk-ai-agent/02-capability-extension/skill-management">/02-capability-extension/skill-management</a></td></tr><tr><td>MCP</td><td>Model Context Protocol（模型上下文协议）</td><td>Agent 与 Tool/Resource/Prompt 之间的标准化 client-server 通信协议</td><td><a href="/fk-ai-agent/02-capability-extension/mcp">/02-capability-extension/mcp</a></td></tr><tr><td>RAG</td><td>检索增强生成（Retrieval-Augmented Generation）</td><td>先检索外部知识再生成，缓解模型参数知识过时与幻觉</td><td><a href="/fk-ai-agent/03-context-memory/rag">/03-context-memory/rag</a></td></tr><tr><td>Checkpoint</td><td>检查点</td><td>运行中保存的可恢复状态快照，用于会话恢复与回滚</td><td><a href="/fk-ai-agent/03-context-memory/session-state">/03-context-memory/session-state</a></td></tr><tr><td>Context Window</td><td>上下文窗口</td><td>单次推理可容纳的 token 上限，决定可注入信息的容量</td><td><a href="/fk-ai-agent/03-context-memory/context-window">/03-context-memory/context-window</a></td></tr><tr><td>Prompt Injection</td><td>提示注入</td><td>攻击者通过外部内容把恶意指令混入模型上下文的攻击</td><td><a href="/fk-ai-agent/05-safety-governance/prompt-injection">/05-safety-governance/prompt-injection</a></td></tr><tr><td>Guardrails</td><td>安全护栏</td><td>对输入/输出/行为的过滤与拦截层，限制 Agent 越界</td><td><a href="/fk-ai-agent/05-safety-governance/guardrails">/05-safety-governance/guardrails</a></td></tr><tr><td>Kill Switch</td><td>紧急停止开关</td><td>运行时熔断机制，立即中止 Agent 执行（区别于事后回滚）</td><td><a href="/fk-ai-agent/05-safety-governance/kill-switch">/05-safety-governance/kill-switch</a></td></tr><tr><td>ReAct</td><td>Reason + Act（推理-行动）</td><td>走一步看一步的推理-行动交织范式</td><td><a href="/fk-ai-agent/01-agent-basics/agent-loop">/01-agent-basics/agent-loop</a></td></tr><tr><td>Plan-and-Execute</td><td>先规划后执行</td><td>先产出完整计划再逐步执行的范式，区别于 ReAct</td><td><a href="/fk-ai-agent/04-planning-execution/plan-and-execute">/04-planning-execution/plan-and-execute</a></td></tr><tr><td>Orchestrator-Worker</td><td>编排者-工作者</td><td>主 Agent 拆解任务、委派子 Agent、聚合结果的多 Agent 模式</td><td><a href="/fk-ai-agent/02-capability-extension/multi-agent">/02-capability-extension/multi-agent</a></td></tr><tr><td>A2A</td><td>Agent-to-Agent（智能体间通信）</td><td>Agent 之间的任务委派与结果交换协议，区别于 MCP 的 Agent-Tool 通信</td><td><a href="/fk-ai-agent/02-capability-extension/multi-agent">/02-capability-extension/multi-agent</a></td></tr><tr><td>OTEL</td><td>OpenTelemetry（开放遥测）</td><td>厂商无关的可观测性埋点标准，定义 trace/span 等语义约定</td><td><a href="/fk-ai-agent/06-engineering-ops/observability-otel-langfuse">/06-engineering-ops/observability-otel-langfuse</a></td></tr><tr><td>Langfuse</td><td>—</td><td>开源 LLM 可观测平台，OTel-native，提供 trace 可视化与评测</td><td><a href="/fk-ai-agent/06-engineering-ops/observability-otel-langfuse">/06-engineering-ops/observability-otel-langfuse</a></td></tr><tr><td>SWE-bench</td><td>—</td><td>软件工程修复基准（给定 issue + 仓库，要求生成通过测试的补丁）</td><td><a href="/fk-ai-agent/06-engineering-ops/evaluation-swebench">/06-engineering-ops/evaluation-swebench</a></td></tr><tr><td>mem0</td><td>—</td><td>面向 LLM 应用的长期记忆层，提供记忆的增删改查与抽取</td><td><a href="/fk-ai-agent/03-context-memory/long-term-memory">/03-context-memory/long-term-memory</a></td></tr><tr><td>Compaction</td><td>上下文压缩</td><td>对过长上下文做摘要/裁剪以适配窗口的过程</td><td><a href="/fk-ai-agent/03-context-memory/context-window">/03-context-memory/context-window</a></td></tr><tr><td>Human-in-the-loop</td><td>人在回路</td><td>在关键节点引入人工审批/确认的控制机制</td><td><a href="/fk-ai-agent/05-safety-governance/audit-rollback">/05-safety-governance/audit-rollback</a></td></tr><tr><td>Fallback</td><td>降级/回退</td><td>主路径失败或超预算时切换到的备选路径或模型</td><td><a href="/fk-ai-agent/04-planning-execution/error-recovery">/04-planning-execution/error-recovery</a></td></tr><tr><td>Side-effect Tool</td><td>副作用工具</td><td>执行会产生外部状态变更的工具（写文件、发邮件、调 API）</td><td><a href="/fk-ai-agent/01-agent-basics/concurrency">/01-agent-basics/concurrency</a></td></tr><tr><td>Idempotent Tool</td><td>幂等工具</td><td>重复调用产生相同结果、无额外副作用的工具</td><td><a href="/fk-ai-agent/01-agent-basics/tool-abstraction">/01-agent-basics/tool-abstraction</a></td></tr></tbody></table><hr><p><em>最后核实日期：2026-08-26</em></p>',5)])])}const p=e(r,[["render",o]]);export{m as __pageData,p as default};
